export default async function(req, sw) {
  const user = await sw.auth.requireUser(req);
  const { title, created_by } = await req.json();
  if (req.method === 'POST') await sw.db.server.insert('cards', { title, created_by });
  const card = await sw.db.server.get('cards', 'c1');
  if (card.created_by !== user.id) return new Response('forbidden', { status: 403 });
  return Response.json(card);
}

