functions.api/lists.ts:
export default async function(req, sw) {
  const user = await sw.auth.requireUser(req);
  const b = await req.json();
  const list = await sw.db.server.get('lists', b.list_id);
  const rows = (await sw.db.server.from('cards')).data.filter(r => r.list_id === list.id);
  await sw.db.server.insert('cards', { title: b.title, list_id: b.list_id, created_by: user.id });
  return Response.json({ rows, by: user.id });
}

functions.api/accept.ts:
export default async function(req, sw) {
  const user = await sw.auth.requireUser(req);
  const b = await req.json();
  const res = await fetch('https://example.com/api/*', { headers: { accept: '*/*' } });
  await sw.db.server.insert('cards', { title: b.title, created_by: user.id });
  if (b.card.created_by !== user.id) return new Response('no', { status: 403 });
  return res;
}

