functions.api/queue.ts:
export default async function(req, sw) {
  let next = await sw.db.server.get('outbox', 'head');
  while (next) {
    await sw.email.send({ to: next.to, subject: next.subject, text: next.text });
    next = await sw.db.server.get('outbox', next.after);
  }
  return Response.json({ ok: true });
}

