functions.api/batch.ts:
export default async function(req, sw) {
  const { data: ms } = await sw.db.server.from('members');
  for (let i = 0; i < ms.length; i += 5) {
    await Promise.allSettled(ms.slice(i, i + 5).map(async (m) => await sw.email.send({ to: m.email, subject: 'Hi', text: 'x' })));
  }
  return Response.json({ ok: true });
}

