functions.api/nested.ts:
export default async function(req, sw) {
  const jobs = [];
  for (const m of [1, 2]) {
    const send = async () => await sw.email.send({ to: 'x@example.com', subject: String(m), text: 'x' });
    jobs.push(send);
    jobs.push(async function later() { await sw.email.send({ to: 'y@example.com', subject: 'y', text: 'y' }); });
  }
  // for (const m of list) await sw.email.send(m)
  const note = 'for (const m of list) await sw.email.send(m)';
  return Response.json({ n: jobs.length, note });
}

